import bisect
class Solution:
    def primeSubarray(self, nums: List[int], k: int) -> int:
        N = 50001
        isp = [True] * N; isp[0] = isp[1] = False
        for i in range(2, int(N ** .5) + 1):
            if isp[i]:
                for j in range(i*i, N, i): isp[j] = False
        n = len(nums)
        LOG = max(1, n.bit_length())
        mx = [[0]*n for _ in range(LOG)]; mn = [[0]*n for _ in range(LOG)]
        for i, x in enumerate(nums):
            mx[0][i] = x if isp[x] else 0
            mn[0][i] = x if isp[x] else float('inf')
        for j in range(1, LOG):
            for i in range(n - (1 << j) + 1):
                h = 1 << (j - 1)
                mx[j][i] = max(mx[j-1][i], mx[j-1][i+h])
                mn[j][i] = min(mn[j-1][i], mn[j-1][i+h])
        def spread(lo, hi):
            j = (hi - lo + 1).bit_length() - 1
            return max(mx[j][lo], mx[j][hi - (1 << j) + 1]) - min(mn[j][lo], mn[j][hi - (1 << j) + 1])
        primes = [i for i, x in enumerate(nums) if isp[x]]
        ans = 0
        for r in range(n):
            m = bisect.bisect_right(primes, r)
            if m < 2: continue
            lo, hi = 0, r
            while lo < hi:
                mid = (lo + hi) // 2
                if spread(mid, r) <= k: hi = mid
                else: lo = mid + 1
            ans += max(0, primes[m - 2] - lo + 1)
        return ans

