class Solution {
    public int primeSubarray(int[] nums, int k) {
        final int N = 50001;
        boolean[] isp = new boolean[N]; Arrays.fill(isp, true); isp[0] = isp[1] = false;
        for (int i = 2; i * i < N; i++) if (isp[i]) for (int j = i * i; j < N; j += i) isp[j] = false;
        int n = nums.length, LOG = 1;
        while ((1 << LOG) < n) LOG++;
        int[][] mx = new int[LOG][n], mn = new int[LOG][n];
        for (int i = 0; i < n; i++) { mx[0][i] = isp[nums[i]] ? nums[i] : 0; mn[0][i] = isp[nums[i]] ? nums[i] : Integer.MAX_VALUE; }
        for (int j = 1; j < LOG; j++) for (int i = 0; i + (1 << j) <= n; i++) {
            mx[j][i] = Math.max(mx[j-1][i], mx[j-1][i + (1 << (j-1))]);
            mn[j][i] = Math.min(mn[j-1][i], mn[j-1][i + (1 << (j-1))]);
        }
        List<Integer> primes = new ArrayList<>();
        for (int i = 0; i < n; i++) if (isp[nums[i]]) primes.add(i);
        long ans = 0;
        for (int r = 0; r < n; r++) {
            int m = Collections.binarySearch(primes, r);
            m = (m >= 0 ? m + 1 : -m - 1);
            if (m < 2) continue;
            int lo = 0, hi = r;
            while (lo < hi) {
                int mid = (lo + hi) >>> 1, len = r - mid + 1, j = 31 - Integer.numberOfLeadingZeros(len);
                int sp = Math.max(mx[j][mid], mx[j][r - (1 << j) + 1]) - Math.min(mn[j][mid], mn[j][r - (1 << j) + 1]);
                if (sp <= k) hi = mid; else lo = mid + 1;
            }
            ans += Math.max(0, primes.get(m - 2) - lo + 1);
        }
        return (int) ans;
    }
}

